// Semantic status colors shared across StatusChip/StatCard/etc. so a
// feature never picks its own ad-hoc "success green" — reused by
// config/theme.config.js too, so these stay in sync with the MUI theme.
export const STATUS_COLORS = {
  success: "#2e7d32",
  warning: "#ed6c02",
  error: "#d32f2f",
  info: "#0288d1",
  neutral: "#616161",
};
